*{box-sizing:border-box} :root{--ink:#202a20;--muted:#758071;--paper:#f4f2e9;--paper-deep:#e8e5d9;--olive:#75845e;--olive-dark:#45563f;--rust:#cb7350;--line:#dcdcd0;--dark:#101611;--mono:'DM Mono',monospace;--serif:'Playfair Display',Georgia,serif;--sans:'DM Sans',sans-serif}html,body{margin:0;min-height:100%;font-family:var(--sans);color:var(--ink);background:var(--dark)}body{min-height:100vh}.grain{position:fixed;inset:0;pointer-events:none;z-index:5;opacity:.035;background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.9' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.5'/%3E%3C/svg%3E")}button,input{font:inherit}button{cursor:pointer}#app{min-height:100vh}.hidden{display:none!important}.gate{position:relative;display:grid;grid-template-columns:1fr 1fr;width:min(1180px,calc(100% - 64px));min-height:690px;margin:6vh auto;background:var(--paper);overflow:hidden;box-shadow:0 24px 90px #0005}.gate-art{position:relative;min-height:690px;overflow:hidden;background:linear-gradient(180deg,#b7bda0 0%,#d1c9a7 49%,#e0bd88 72%,#887d5c 100%)}.sun{position:absolute;width:170px;height:170px;border-radius:50%;background:#eed7a1;top:17%;left:50%;transform:translateX(-50%);box-shadow:0 0 95px 28px #f4dfb388}.ridge{position:absolute;inset:auto -12% 0;height:58%;clip-path:polygon(0 82%,12% 70%,25% 80%,42% 42%,55% 61%,66% 33%,81% 75%,91% 61%,100% 70%,100% 100%,0 100%)}.ridge-back{height:51%;background:#7f896d;opacity:.86;transform:translateY(-21px);clip-path:polygon(0 84%,14% 57%,29% 79%,43% 38%,59% 67%,76% 34%,89% 75%,100% 57%,100% 100%,0 100%)}.ridge-front{background:#465743}.road{position:absolute;bottom:-2%;left:53%;width:43%;height:62%;background:#c9a674;clip-path:polygon(42% 0,58% 0,65% 38%,100% 100%,4% 100%,35% 39%);opacity:.75}.road:after{content:'';position:absolute;inset:0;background:#f3ddb0;clip-path:polygon(48% 0,51% 0,54% 40%,64% 100%,54% 100%,46% 41%)}.art-label{position:absolute;left:34px;bottom:29px;font:10px var(--mono);letter-spacing:.13em;color:#e8e2cc}.gate-copy{padding:83px 12% 78px 12%;display:flex;flex-direction:column;justify-content:center}.eyebrow,.card-kicker,.log-heading,.gate-footer,.story-footer,.topbar-center,.topbar-right>span,.weather-tag{font:10px var(--mono);letter-spacing:.12em}.eyebrow{display:flex;align-items:center;gap:10px;color:#77836d}.eyebrow-dot,.pulse-dot,.live-indicator{width:7px;height:7px;border-radius:50%;background:#a86a49;display:inline-block}.gate h1{font:600 clamp(60px,7vw,86px)/1 var(--serif);letter-spacing:-.055em;margin:23px 0 10px;color:#263227}.gate h1 span,.wordmark span{color:var(--rust)}.gate-subtitle{font:20px var(--serif);margin:0;color:#58614f}.gate-description{font-size:13px;line-height:1.75;color:#777c6c;max-width:340px;margin:19px 0 31px}.join-form{display:flex;flex-direction:column}.join-form label{font:10px var(--mono);letter-spacing:.11em;color:#757b6d;margin:0 0 9px}.label-note{letter-spacing:0;text-transform:none;font-family:var(--sans);font-size:11px;color:#a1a393}.join-form input{height:45px;padding:0 13px;border:1px solid #d5d6c9;background:#f9f8f2;outline:0;color:var(--ink);font-size:13px;margin-bottom:19px}.join-form input:focus{border-color:#879578;box-shadow:0 0 0 3px #8a9b7330}.join-form input::placeholder{color:#aaa99a;font:10px var(--mono);letter-spacing:.04em}.room-entry{display:flex;gap:8px}.room-entry input{flex:1}.dice-button{height:45px;width:46px;margin-top:0;border:1px solid #d5d6c9;background:#efeee5;color:#68745d;font-size:21px}.primary-button{background:#455841;border:0;color:#f6f2e5;display:flex;align-items:center;justify-content:space-between;padding:0 17px;height:49px;font-size:12px;letter-spacing:.025em;transition:background .2s,transform .2s}.primary-button:hover{background:#344632;transform:translateY(-1px)}.button-arrow{font-size:17px}.join-note{font-size:11px;color:#8d9182;margin-top:17px;display:flex;align-items:center;gap:8px}.join-note .pulse-dot{width:6px;height:6px;background:#81936c}.gate-footer{position:absolute;bottom:0;left:0;right:0;height:48px;display:flex;align-items:center;justify-content:space-between;padding:0 37px;color:#8a8b7b;border-top:1px solid #dcdcd0;font-size:9px}.error-message{color:#a84937;min-height:16px;font-size:12px;margin:8px 0 0}.game-shell{min-height:100vh;background:var(--paper)}.topbar{height:68px;background:var(--dark);color:#e9e9dc;display:flex;align-items:center;justify-content:space-between;padding:0 max(calc((100vw - 1200px)/2),36px);}.wordmark{font:600 25px var(--serif);letter-spacing:-.05em;color:#f3f0e5;text-decoration:none}.topbar-center{display:flex;align-items:center;gap:9px;color:#c0c3b4;font-size:9px;letter-spacing:.11em}.live-indicator{background:#9da87b;width:6px;height:6px;box-shadow:0 0 0 3px #9da87b22}.topbar-separator{opacity:.35}.topbar-right{display:flex;align-items:center;gap:19px}.topbar-right>span{font-size:10px;color:#d0d2c2}.quiet-button{background:transparent;border:0;color:#9da392;font-size:11px}.quiet-button span{color:#d28763;margin-left:4px}.game-grid{width:min(1200px,calc(100% - 72px));margin:0 auto;display:grid;grid-template-columns:minmax(0,1fr) 302px;gap:62px;padding:58px 0 30px}.story-column{min-width:0}.journey-heading{padding:0 5px 24px}.journey-heading h1{font:600 clamp(35px,4vw,47px)/1.15 var(--serif);letter-spacing:-.035em;margin:17px 0 7px}.title-line{display:flex;align-items:center;justify-content:space-between;gap:18px}.weather-tag{white-space:nowrap;border:1px solid #d9d9cc;color:#79806f;padding:8px 10px;font-size:8px}.location-caption{margin:0;color:#7f8576;font-size:13px}.route-strip{display:grid;grid-template-columns:repeat(6,1fr);margin:2px 0 37px;position:relative;padding:0 3px}.route-strip:before{content:'';height:1px;background:#d3d5c8;position:absolute;top:7px;left:7px;right:7px}.route-stop{position:relative;display:flex;align-items:center;flex-direction:column;gap:9px;text-align:center}.route-point{width:14px;height:14px;border:1px solid #b9bead;background:var(--paper);border-radius:50%;z-index:1}.route-stop.done .route-point{background:#75845e;border-color:#75845e;box-shadow:inset 0 0 0 3px var(--paper)}.route-stop.current .route-point{width:15px;height:15px;border:4px solid #7d8c68;background:#f4f2e9;box-shadow:0 0 0 3px #7d8c6824}.route-name{font:8px var(--mono);letter-spacing:.06em;color:#9a9c8d;max-width:80px;text-transform:uppercase;line-height:1.5}.route-stop.current .route-name{color:#59694d}.log-heading{display:flex;justify-content:space-between;align-items:center;color:#808678;border-bottom:1px solid var(--line);padding:0 3px 12px;font-size:9px}.log-heading span:last-child{font-size:8px;color:#a5a694}.journal{height:268px;overflow-y:auto;padding:18px 4px 10px;display:flex;flex-direction:column;gap:18px;scrollbar-width:thin;scrollbar-color:#c3c6b7 transparent}.journal-entry{display:grid;grid-template-columns:48px 1fr;gap:12px;animation:arrive .3s ease-out}.journal-time{font:9px var(--mono);color:#a2a493;padding-top:4px}.journal-text{font:14px/1.65 var(--serif);color:#586052}.journal-entry.system .journal-text{font-family:var(--sans);font-size:12px;color:#7d8275}.journal-entry.highlight .journal-text{color:#3f573d}.journal-author{font:9px var(--mono);color:#9a7259;letter-spacing:.04em;display:block;margin-bottom:4px}.journal-entry.event .journal-text{padding:11px 14px;border-left:2px solid #cb835e;background:#eeece1}.action-area{border-top:1px solid var(--line);padding:19px 3px 13px;min-height:156px}.action-title{display:flex;justify-content:space-between;align-items:center;margin-bottom:12px}.action-title strong{font:600 13px var(--sans);color:#485344}.action-title span{font:9px var(--mono);color:#929788}.action-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:8px}.action-card{position:relative;text-align:left;background:#eeede4;border:1px solid #ddded1;padding:13px 10px 12px;min-height:79px;color:var(--ink);transition:all .16s}.action-card:hover:not(:disabled){background:#e8e9dc;border-color:#879679;transform:translateY(-2px)}.action-card:disabled{opacity:.48;cursor:not-allowed}.action-card .action-icon{font-size:17px;color:#75845e;display:block;margin-bottom:6px}.action-card strong{font-size:11px;font-weight:600;display:block}.action-card small{font-size:9px;color:#8b9082;display:block;margin-top:4px;line-height:1.35}.action-card.encounter-choice{border-color:#c9a28d;background:#f0e8dd}.action-card.encounter-choice:hover:not(:disabled){border-color:#bc7859;background:#f3e5d6}.action-card.encounter-choice .action-icon{color:#ba7655}.wait-panel,.finished-panel{background:#e9eade;padding:14px 16px;display:flex;justify-content:space-between;align-items:center;color:#727967;font-size:12px}.wait-panel strong,.finished-panel strong{display:block;color:#4f5c46;font-size:12px;margin-bottom:4px}.wait-panel small,.finished-panel small{font-size:10px;color:#8b9082}.wait-icon{font-size:19px;color:#a37859}.story-footer{display:flex;justify-content:space-between;color:#a2a393;font-size:8px;border-top:1px solid #deded3;padding:17px 3px 0}.sidebar{display:flex;flex-direction:column;gap:15px}.status-card,.supplies-card,.map-card{border:1px solid #dedfd3;background:#f8f7f0;padding:17px 17px 15px}.card-kicker{display:flex;justify-content:space-between;color:#72796c;font-size:9px;align-items:center}.card-kicker span:last-child{font-size:8px;color:#a0a391}.party-list{margin-top:15px;display:flex;flex-direction:column;gap:10px}.party-member{display:flex;align-items:center;gap:10px;font-size:12px;color:#4d5849}.avatar{height:29px;width:29px;border-radius:50%;display:grid;place-items:center;background:#e1e4d4;color:#596c50;font:11px var(--serif);position:relative}.avatar:after{content:'';position:absolute;width:6px;height:6px;background:#91a177;bottom:-1px;right:-1px;border-radius:50%;border:1px solid #f8f7f0}.party-member.away .avatar:after{background:#c1bba8}.party-role{margin-left:auto;font:8px var(--mono);color:#9c9f90}.turn-status{border-top:1px solid #e4e4da;margin-top:14px;padding-top:12px;color:#8a8e80;font-size:10px;line-height:1.5}.turn-status b{color:#57654d;font-weight:600}.supplies-card{padding-bottom:14px}.supply-note{font-size:7px!important}.supply-row{display:flex;align-items:center;gap:10px;margin:18px 0 8px}.supply-icon{font-size:14px;width:27px;height:27px;border-radius:50%;display:grid;place-items:center;background:#edebe0;color:#ad7a51}.spirit-icon{color:#829064}.supply-copy{display:flex;flex-direction:column;gap:3px;flex:1}.supply-copy span{font-size:11px;color:#56604f}.supply-copy small{font-size:9px;color:#9a9d8e}.supply-row strong{font:500 17px var(--mono);color:#56654d}.meter{height:3px;background:#e7e7dc;margin-left:37px}.meter-fill{height:100%;background:#c28a5b;transition:width .3s}.spirit-fill{background:#7c8e66}.map-card{padding-bottom:11px}.map-art{position:relative;height:118px;margin:13px -2px 9px;overflow:hidden;background-color:#eeede1;background-image:radial-gradient(#9da68a 0.6px,transparent .6px);background-size:8px 8px}.map-orbit{position:absolute;border:1px solid #c9cbb9;opacity:.75;border-radius:50%;transform:rotate(-25deg)}.orbit-one{width:190px;height:76px;top:24px;left:46px}.orbit-two{width:148px;height:102px;top:11px;left:61px;transform:rotate(22deg)}.map-route-line{position:absolute;left:17%;right:17%;top:54%;height:2px;background:#a5ad91;transform:rotate(-12deg)}.map-marker{position:absolute;z-index:1;display:grid;place-items:center}.marker-start{left:15%;top:50%;color:#52634b;font-size:14px}.marker-end{right:13%;top:24%;font-size:14px;color:#bd7953}.marker-you{left:15%;top:50%;font-size:15px;color:#c77d57;transition:left .35s,top .35s;text-shadow:0 0 3px white}.map-coordinate{position:absolute;bottom:8px;left:9px;font:7px var(--mono);color:#9a9d8d;letter-spacing:.06em}.map-compass{position:absolute;right:8px;bottom:7px;font:8px/1.2 var(--mono);color:#7a8471;text-align:center}.map-caption{display:flex;justify-content:space-between;color:#7a8370;font:8px var(--mono);letter-spacing:.07em}.map-caption span:last-child{color:#aa7956}.share-card{display:flex;align-items:center;gap:10px;background:#e8e8db;padding:13px 12px}.share-icon{width:29px;height:29px;background:#dce1d2;color:#64755b;display:grid;place-items:center;font-size:15px}.share-card>div{display:flex;flex-direction:column;gap:3px;flex:1}.share-card strong{font-size:10px;color:#55614e}.share-card small{font-size:9px;color:#8e9382}.share-card small b{font:10px var(--mono);letter-spacing:.08em;color:#a36d50}.share-card button{background:transparent;border:0;color:#7e8773;font-size:17px;padding:4px}.sidebar-footnote{font:11px/1.6 var(--serif);color:#858a7a;text-align:center;margin:3px 0}.sidebar-footnote span{font:9px var(--sans);color:#a1a392}.toast{position:fixed;bottom:24px;left:50%;transform:translate(-50%,20px);background:#253226;color:#f4f1e7;padding:11px 17px;font-size:12px;z-index:10;opacity:0;transition:.2s;pointer-events:none;box-shadow:0 5px 20px #0002}.toast.show{opacity:1;transform:translate(-50%,0)}@keyframes arrive{from{opacity:0;transform:translateY(5px)}to{opacity:1;transform:translateY(0)}}
@media(max-width:900px){.game-grid{grid-template-columns:minmax(0,1fr) 265px;gap:27px;width:calc(100% - 48px)}.gate{width:calc(100% - 40px)}.gate-copy{padding-left:9%;padding-right:9%}.action-grid{grid-template-columns:repeat(2,1fr)}.action-area{min-height:230px}.topbar{padding:0 24px}.topbar-center{font-size:8px}}
@media(max-width:650px){.gate{display:flex;flex-direction:column;width:100%;min-height:100vh;margin:0}.gate-art{min-height:230px;height:230px}.sun{width:95px;height:95px;top:11%}.ridge{height:75%}.ridge-back{height:65%}.road{height:75%;width:50%}.gate-copy{padding:35px 28px 78px}.gate h1{font-size:62px;margin-top:17px}.gate-description{margin:12px 0 23px}.gate-footer{padding:0 20px;font-size:7px}.topbar{height:57px;padding:0 17px}.wordmark{font-size:23px}.topbar-center{display:none}.topbar-right{gap:10px}.quiet-button{font-size:10px}.game-grid{display:flex;flex-direction:column-reverse;width:calc(100% - 34px);padding:25px 0 23px;gap:23px}.sidebar{display:grid;grid-template-columns:1fr 1fr;gap:10px}.status-card,.supplies-card,.map-card{padding:13px}.party-list{gap:7px}.party-member{font-size:10px}.avatar{height:25px;width:25px}.turn-status{font-size:9px;margin-top:9px;padding-top:8px}.supply-copy small{font-size:8px}.supply-row{gap:7px}.map-card{grid-column:span 2}.map-art{height:94px}.share-card{grid-column:span 2}.sidebar-footnote{grid-column:span 2}.journey-heading{padding:0 2px 20px}.journey-heading h1{font-size:34px}.weather-tag{font-size:7px;padding:7px}.route-strip{margin-bottom:26px}.route-name{font-size:7px}.journal{height:230px}.story-footer{font-size:7px}.story-footer span:last-child{display:none}.action-grid{grid-template-columns:repeat(2,1fr)}.action-area{min-height:220px}.action-card{min-height:74px}.gate-footer span:last-child{max-width:130px;text-align:right}.status-card{grid-column:span 2}.supplies-card{grid-column:span 2}}
@media(min-width:651px) and (max-height:850px){.game-grid{padding-top:36px}.journal{height:220px}.gate{min-height:640px;margin-top:4vh}.gate-art{min-height:640px}}

import http from 'node:http';
import { readFile } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { randomBytes } from 'node:crypto';

const ROOT = path.dirname(fileURLToPath(import.meta.url));
const PORT = Number(process.env.PORT || 3002);
const rooms = new Map();
const stops = ['The Ember Ferry', 'The Bracken Mile', 'Glasswater Ford', 'Bellweather', 'The Old Observatory', 'Home'];
const captions = ['Where the old road begins to disappear.', 'A green corridor, tangled with old stories.', 'The river keeps a thousand borrowed skies.', 'A village built to listen for the wind.', 'A quiet place above the clouds.', 'The long way home, made shorter together.'];
const weather = ['CLEAR SKIES', 'A SOFT DRIZZLE', 'WIND FROM THE WEST', 'LOW MIST', 'GOLDEN AFTERNOON'];
const encounters = {
  1: { title: 'The lantern post', text: 'At the first bend, a lantern burns in an empty post. Its warm light points toward a narrow path through the ferns. The old road goes the other way.', options: [{ label: 'Follow the little light', icon: '✦', detail: 'Spend 1 provision · lift party spirit', food: -1, morale: 2, insight: 0, text: 'You follow the lantern through the ferns. Someone has left a tiny painted star on the next stone.' }, { label: 'Keep to the old road', icon: '↗', detail: 'Read the old markers · gain 2 clues', food: 0, morale: -1, insight: 2, text: 'The old mile markers tell their story in worn symbols. You copy them into the journal.' }] },
  2: { title: 'Glasswater crossing', text: 'Glasswater is running high. A half-sunken stone bridge crosses upstream; closer by, the river opens into a shallow, pebbled ford.', options: [{ label: 'Try the stone bridge', icon: '⌁', detail: 'A careful crossing · gain a clue', food: -2, morale: 0, insight: 1, text: 'The bridge holds. In the stonework you find a map scratched by someone who came before.' }, { label: 'Wade through the ford', icon: '≈', detail: 'Find fresh water · spend 1 spirit', food: 2, morale: -1, insight: 0, text: 'Cold water to your knees, clear water in your bottles. The far bank is closer than it looked.' }] },
  3: { title: 'The quiet caravan', text: 'A little caravan is resting beneath a cedar. Its travelers have warm tea, patched coats, and no interest in hurrying.', options: [{ label: 'Trade stories over tea', icon: '☼', detail: 'A good conversation · spirit +2, clue +1', food: 0, morale: 2, insight: 1, text: 'You share a story apiece. By the time the kettle cools, the road feels friendlier.' }, { label: 'Trade for their provisions', icon: '⇄', detail: 'Give 2 clues · gain 4 provisions', food: 4, morale: 0, insight: -2, text: 'A fair trade, sealed with a handshake. The caravan points you toward the western ridge.' }] },
  4: { title: 'The old observatory', text: 'The observatory sits above the cloudline, its brass dome open to the evening. A narrow stair climbs to the roof; a sheltered courtyard waits below.', options: [{ label: 'Climb to the roof', icon: '↑', detail: 'Spend 2 spirit · find 2 clues', food: 0, morale: -2, insight: 2, text: 'From the roof, the whole road reveals itself. You sketch the last miles before the clouds drift in.' }, { label: 'Rest in the courtyard', icon: '⌂', detail: 'Settle in · lift party spirit', food: 0, morale: 2, insight: 0, text: 'You rest in the sheltered courtyard, listening to the dome hum softly in the wind.' }] }
};

function makeRoomCode() {
  const alphabet = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';
  return Array.from(randomBytes(5), byte => alphabet[byte % alphabet.length]).join('');
}
function addLog(room, text, author = 'FIELD NOTE', kind = 'system') {
  room.log.push({ id: randomBytes(5).toString('hex'), text, author, kind, time: Date.now() });
  if (room.log.length > 70) room.log.splice(0, room.log.length - 70);
}
function createRoom(code) {
  return { code, created: Date.now(), day: 1, distance: 0, food: 16, morale: 8, insight: 0, state: 'playing', weather: weather[0], acted: [], pending: null, resolved: [], players: [], log: [{ id: 'welcome', text: 'The map ends here. Six pencilled miles lead into the wilds, and a small ferry waits at the water’s edge. The road is yours to make.', author: 'FIELD NOTE', kind: 'system', time: Date.now() }] };
}
function cleanRoom(room) {
  const now = Date.now();
  room.players = room.players.filter(player => now - player.seen < 24 * 60 * 60 * 1000);
}
function viewRoom(room, playerId) {
  cleanRoom(room);
  const now = Date.now();
  const online = room.players.filter(player => now - player.seen < 18000);
  return {
    code: room.code, day: room.day, distance: room.distance, food: room.food, morale: room.morale, insight: room.insight,
    state: room.state, weather: room.weather, stops, captions, log: room.log, pending: room.pending,
    players: room.players.map(player => ({ id: player.id, name: player.name, online: now - player.seen < 18000, acted: room.acted.includes(player.id) })),
    partyCount: Math.max(1, online.length), meActed: room.acted.includes(playerId),
    activeCount: online.length, resolved: room.resolved
  };
}
function advanceDay(room) {
  if (room.state !== 'playing') return;
  const online = room.players.filter(player => Date.now() - player.seen < 18000);
  if (!online.length || !online.every(player => room.acted.includes(player.id))) return;
  if (room.distance >= stops.length - 1) {
    room.state = 'won';
    addLog(room, 'The last hill falls away. There you are: home, with the whole road behind you and one another beside you.', 'FIELD NOTE', 'highlight');
    return;
  }
  room.day += 1;
  room.acted = [];
  const ration = Math.max(1, online.length);
  const spent = Math.min(room.food, ration);
  room.food -= spent;
  if (spent < ration) {
    room.morale = Math.max(0, room.morale - (ration - spent));
    addLog(room, 'Dawn arrives, but there are not enough provisions for everyone. The quiet is harder to carry.', 'FIELD NOTE', 'event');
  } else {
    addLog(room, `Dawn. ${ration} ${ration === 1 ? 'ration is' : 'rations are'} shared around the campfire.`, 'FIELD NOTE', 'system');
  }
  room.weather = weather[(room.day - 1) % weather.length];
  if (room.morale <= 0) {
    room.state = 'lost';
    addLog(room, 'The party has run out of heart. The road will wait here until you are ready to try again.', 'FIELD NOTE', 'event');
  }
}
function applyAction(room, player, action) {
  const name = player.name;
  if (action === 'travel') {
    if (room.distance >= stops.length - 1) throw new Error('You have reached the end of the road.');
    if (room.food < 2) throw new Error('You need 2 provisions to travel. Gather some first.');
    room.food -= 2;
    room.distance += 1;
    addLog(room, `${name} leads the party onward, following the path toward ${stops[room.distance]}. Two provisions go into the pack; the map gains another mile.`, name, 'highlight');
    if (encounters[room.distance] && !room.resolved.includes(room.distance)) {
      room.pending = { distance: room.distance, ...encounters[room.distance] };
      addLog(room, encounters[room.distance].text, 'A MOMENT ON THE ROAD', 'event');
    }
  } else if (action === 'forage') {
    room.food = Math.min(30, room.food + 4);
    addLog(room, `${name} gathers wild pears and a handful of good roots. The party adds 4 provisions.`, name, 'highlight');
  } else if (action === 'rest') {
