91:     addLog(room, `${name} makes a proper camp. A hot drink and a little rest bring the party spirit to ${room.morale}${before === room.morale ? ' (already full)' : ' (+2)'}.`, name, 'highlight');
92:   } else if (action === 'scout') {
93:     room.insight += 1;
94:     addLog(room, `${name} studies the folds of the land and marks a detail the map had missed. The party gains a clue.`, name, 'highlight');
95:   } else if (action.startsWith('event-')) {
96:     if (!room.pending) throw new Error('That moment has already passed.');
97:     const option = room.pending.options[Number(action.slice(6))];
98:     if (!option) throw new Error('That choice is not available.');
99:     if (room.food + option.food < 0) throw new Error('The party does not have enough provisions for that choice.');
100:     if (room.insight + option.insight < 0) throw new Error('You need more clues to make that trade.');
101:     room.food = Math.max(0, room.food + option.food);
102:     room.morale = Math.max(0, Math.min(10, room.morale + option.morale));
