145:         cleanRoom(room);
146:         let player = room.players.find(item => item.id === playerId);
147:         if (!player && room.players.length >= 6) return send(res, 409, { error: 'This party is full. A journey can hold up to 6 travelers.' });
148:         if (!player) {
