152:         } else player.name = name;
153:         player.seen = Date.now();
154:         return send(res, 200, { room: viewRoom(room, playerId), playerId });
155:       }
156:       if (req.method === 'GET' && url.pathname === '/api/room') {
157:         const code = String(url.searchParams.get('code') || '').toUpperCase();
158:         const playerId = String(url.searchParams.get('playerId') || '');
159:         const room = rooms.get(code);
160:         if (!room) return send(res, 404, { error: 'This room is no longer here. Begin a new journey to make another.' });
161:         const player = room.players.find(item => item.id === playerId);
162:         if (!player) return send(res, 403, { error: 'You are not part of this journey. Rejoin using its room code.' });
