177:         catch (error) { return send(res, 400, { error: error.message }); }
178:         return send(res, 200, { room: viewRoom(room, player.id) });
179:       }
180:       if (req.method === 'POST' && url.pathname === '/api/leave') {
181:         const body = await readBody(req);
182:         const room = rooms.get(String(body.code || '').toUpperCase());
183:         if (room) {
184:           room.players = room.players.filter(player => player.id !== String(body.playerId || ''));
185:           room.acted = room.acted.filter(id => id !== String(body.playerId || ''));
186:           addLog(room, `${String(body.name || 'A traveler').slice(0, 18)} leaves the trail.`, 'FIELD NOTE', 'system');
187:           advanceDay(room);
188:         }
189:         return send(res, 200, { ok: true });
190:       }
191:       return send(res, 404, { error: 'Not found.' });
192:     }
193:     let pathname = decodeURIComponent(url.pathname);
194:     if (pathname === '/') pathname = '/index.html';
195:     const fullPath = path.resolve(ROOT, `.${pathname}`);
196:     if (!fullPath.startsWith(ROOT + path.sep)) { res.writeHead(403); res.end('Forbidden'); return; }
197:     const file = await readFile(fullPath);
198:     res.writeHead(200, { 'Content-Type': contentTypes[path.extname(fullPath)] || 'application/octet-stream', 'Cache-Control': 'no-cache' });
199:     res.end(file);
200:   } catch (error) {
201:     if (error instanceof SyntaxError) return send(res, 400, { error: 'Invalid request.' });
202:     if (error.code === 'ENOENT') { res.writeHead(404); res.end('Not found'); return; }
203:     console.error(error);
204:     send(res, 500, { error: 'Something went wrong on the trail. Please try again.' });
205:   }
206: });
207: server.listen(PORT, '0.0.0.0', () => console.log(`Wayfarer is listening on http://localhost:${PORT}`));

