node --input-type=module <<'EOF'
const base='http://localhost:3002';
const post=async(path,data)=>{const r=await fetch(base+path,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(data)});return [r.status,await r.json()]};
let [status,{room}]=await post('/api/join',{name:'Rowan',playerId:'verify-rowan'});
if(status!==200) throw new Error('create failed');
const code=room.code;
let [status2, second]=await post('/api/join',{name:'Juniper',playerId:'verify-juniper',code});
if(status2!==200) throw new Error('join failed');
let [status3, moved]=await post('/api/action',{code,playerId:'verify-rowan',action:'travel'});
if(status3!==200) throw new Error('travel failed');
let [status4, choice]=await post('/api/action',{code,playerId:'verify-juniper',action:'event-1'});
if(status4!==200) throw new Error('encounter failed');
const days=choice.room.log.map(x=>x.day);
if(days.some(x=>x!==1)) throw new Error('day metadata mismatch: '+days);
if(choice.room.day!==2) throw new Error('co-op day did not advance');
console.log(JSON.stringify({code,players:choice.room.players.map(p=>p.name),day:choice.room.day,logDays:days,insight:choice.room.insight,pending:choice.room.pending},null,2));
await post('/api/leave',{code,playerId:'verify-rowan',name:'Rowan'});
await post('/api/leave',{code,playerId:'verify-juniper',name:'Juniper'});
EOF

